import{_ as d,c as a,o as n,aj as s}from"./chunks/framework.B5VMNd4r.js";const c=JSON.parse('{"title":"第6章 全场景工具链——从创意到交付的AI工作流","description":"","frontmatter":{},"headers":[],"relativePath":"handbook/ai-tools/chapter_6.md","filePath":"handbook/ai-tools/chapter_6.md","lastUpdated":1783615807000}'),e={name:"handbook/ai-tools/chapter_6.md"};function r(p,t,l,i,h,b){return n(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="第6章-全场景工具链——从创意到交付的ai工作流" tabindex="-1">第6章 全场景工具链——从创意到交付的AI工作流 <a class="header-anchor" href="#第6章-全场景工具链——从创意到交付的ai工作流" aria-label="Permalink to “第6章 全场景工具链——从创意到交付的AI工作流”">​</a></h1><p>单个工具再好，不如串成链路。这章把前5章的工具打通，构建从创意到交付的完整AI工作流。</p><p>我是怕浪猫，AI提效工具系列第6章。前面5章逐个介绍了工具，这章做整合。</p><h2 id="_6-1-需求分析-不同场景的工具选型决策树" tabindex="-1">6.1 需求分析：不同场景的工具选型决策树 <a class="header-anchor" href="#_6-1-需求分析-不同场景的工具选型决策树" aria-label="Permalink to “6.1 需求分析：不同场景的工具选型决策树”">​</a></h2><p><strong>选型决策树</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你的需求是什么？</span></span>
<span class="line"><span>├── 内容创作</span></span>
<span class="line"><span>│   ├── 写文章 → Ollama+OpenWebUI + AnythingLLM</span></span>
<span class="line"><span>│   ├── 做图片 → ComfyUI/WebUI + SDXL/FLUX</span></span>
<span class="line"><span>│   ├── 做视频 → ComfyUI + SVD/CogVideoX + Whisper-WebUI</span></span>
<span class="line"><span>│   └── 多语言 → 沉浸式翻译</span></span>
<span class="line"><span>├── 办公效率</span></span>
<span class="line"><span>│   ├── 知识库 → FastGPT（通用）/ RAGFlow（复杂文档）</span></span>
<span class="line"><span>│   ├── AI应用 → Dify（工作流编排）</span></span>
<span class="line"><span>│   ├── 自动化 → n8n（系统集成）</span></span>
<span class="line"><span>│   └── 文档对话 → AnythingLLM</span></span>
<span class="line"><span>├── 开发提效</span></span>
<span class="line"><span>│   ├── 代码补全 → Continue + 本地模型</span></span>
<span class="line"><span>│   ├── 代理编程 → Cline + DeepSeek</span></span>
<span class="line"><span>│   ├── 本地推理 → LocalAI / Ollama</span></span>
<span class="line"><span>│   └── 代码模型 → DeepSeek-Coder / Qwen2.5-Coder</span></span>
<span class="line"><span>└── 全栈AI</span></span>
<span class="line"><span>    ├── 对话平台 → OpenWebUI / LibreChat</span></span>
<span class="line"><span>    ├── 模型运行 → Ollama / LocalAI</span></span>
<span class="line"><span>    └── 工作流 → Dify + n8n</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><p><strong>选型核心原则</strong></p><table tabindex="0"><thead><tr><th>原则</th><th>说明</th></tr></thead><tbody><tr><td>先用再买</td><td>开源工具先试，不够再上商业方案</td></tr><tr><td>少即是多</td><td>3个精通的工具 &gt; 10个浅尝的工具</td></tr><tr><td>数据为王</td><td>模型可以换，数据积累不能丢</td></tr><tr><td>链路思维</td><td>单点优化有限，链路优化才是质变</td></tr><tr><td>隐私分层</td><td>敏感数据本地，非敏感用API</td></tr></tbody></table><h2 id="_6-2-内容创作链路-写作-配图-视频一条龙" tabindex="-1">6.2 内容创作链路：写作+配图+视频一条龙 <a class="header-anchor" href="#_6-2-内容创作链路-写作-配图-视频一条龙" aria-label="Permalink to “6.2 内容创作链路：写作+配图+视频一条龙”">​</a></h2><p><strong>完整链路设计</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>选题策划 → 资料调研 → 初稿撰写 → 配图制作 → 视频化 → 多语言发布</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>各环节工具与职责</strong></p><table tabindex="0"><thead><tr><th>环节</th><th>工具</th><th>输入</th><th>输出</th><th>耗时</th></tr></thead><tbody><tr><td>选题策划</td><td>OpenWebUI + Qwen</td><td>关键词/热点</td><td>选题清单</td><td>10分钟</td></tr><tr><td>资料调研</td><td>AnythingLLM</td><td>参考文档</td><td>摘要+要点</td><td>15分钟</td></tr><tr><td>初稿撰写</td><td>OpenWebUI + DeepSeek</td><td>大纲+要点</td><td>初稿</td><td>30分钟</td></tr><tr><td>配图制作</td><td>ComfyUI + FLUX</td><td>文章主题</td><td>3-5张配图</td><td>20分钟</td></tr><tr><td>视频化</td><td>ComfyUI + SVD</td><td>配图→动图</td><td>短视频素材</td><td>30分钟</td></tr><tr><td>字幕</td><td>Whisper-WebUI</td><td>音频/文本</td><td>SRT字幕</td><td>10分钟</td></tr><tr><td>多语言</td><td>沉浸式翻译</td><td>中文成品</td><td>英文/日文版</td><td>15分钟</td></tr><tr><td>合计</td><td>-</td><td>-</td><td>-</td><td>约2小时</td></tr></tbody></table><p><strong>传统方式对比</strong></p><table tabindex="0"><thead><tr><th>环节</th><th>传统方式</th><th>AI链路</th><th>提升幅度</th></tr></thead><tbody><tr><td>选题策划</td><td>1小时</td><td>10分钟</td><td>83%</td></tr><tr><td>资料调研</td><td>2小时</td><td>15分钟</td><td>87%</td></tr><tr><td>初稿撰写</td><td>4小时</td><td>30分钟</td><td>87%</td></tr><tr><td>配图制作</td><td>1小时</td><td>20分钟</td><td>67%</td></tr><tr><td>视频化</td><td>3小时</td><td>30分钟</td><td>83%</td></tr><tr><td>多语言</td><td>3小时</td><td>15分钟</td><td>92%</td></tr><tr><td>合计</td><td>14小时</td><td>2小时</td><td>86%</td></tr></tbody></table><p><strong>链路优化要点</strong></p><table tabindex="0"><thead><tr><th>要点</th><th>说明</th></tr></thead><tbody><tr><td>模板化</td><td>把每个环节的提示词保存为模板</td></tr><tr><td>批量化</td><td>配图用ComfyUI API批量生成</td></tr><tr><td>中间件</td><td>用n8n串联各环节，减少手动切换</td></tr><tr><td>版本管理</td><td>用Git管理所有中间产物</td></tr><tr><td>反馈循环</td><td>发布后用AnythingLLM分析评论反馈</td></tr></tbody></table><h2 id="_6-3-办公自动化链路-文档处理-知识库-流程自动化" tabindex="-1">6.3 办公自动化链路：文档处理+知识库+流程自动化 <a class="header-anchor" href="#_6-3-办公自动化链路-文档处理-知识库-流程自动化" aria-label="Permalink to “6.3 办公自动化链路：文档处理+知识库+流程自动化”">​</a></h2><p><strong>链路设计</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>文档输入 → 自动分类 → 知识库入库 → 智能检索 → 自动执行 → 结果交付</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>各环节工具</strong></p><table tabindex="0"><thead><tr><th>环节</th><th>工具</th><th>职责</th></tr></thead><tbody><tr><td>文档输入</td><td>n8n Webhook</td><td>接收邮件/上传/API</td></tr><tr><td>自动分类</td><td>n8n + OpenAI节点</td><td>按类型/紧急度分类</td></tr><tr><td>知识库入库</td><td>FastGPT API</td><td>自动分段+向量化</td></tr><tr><td>深度解析</td><td>RAGFlow</td><td>处理表格/公式等复杂内容</td></tr><tr><td>智能检索</td><td>Dify Chatflow</td><td>对话式检索+推理</td></tr><tr><td>自动执行</td><td>n8n</td><td>发邮件/建工单/更新数据库</td></tr><tr><td>结果交付</td><td>n8n → 飞书/邮件/Slack</td><td>多渠道通知</td></tr></tbody></table><p><strong>实战场景：合同审核自动化</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>工具</th><th>操作</th><th>耗时</th></tr></thead><tbody><tr><td>1</td><td>n8n</td><td>收到合同邮件→自动提取附件</td><td>1分钟</td></tr><tr><td>2</td><td>RAGFlow</td><td>解析合同→提取关键条款</td><td>2分钟</td></tr><tr><td>3</td><td>Dify</td><td>AI审核→比对标准模板→标记风险</td><td>3分钟</td></tr><tr><td>4</td><td>n8n</td><td>生成审核报告→发送给法务</td><td>1分钟</td></tr><tr><td>5</td><td>FastGPT</td><td>合同存入知识库→可后续查询</td><td>1分钟</td></tr><tr><td>合计</td><td>-</td><td>-</td><td>8分钟</td></tr></tbody></table><blockquote><p>传统合同审核：人工阅读30-60分钟。AI链路：8分钟完成初筛，法务只看AI标记的风险点。</p></blockquote><h2 id="_6-4-开发提效链路-代码生成-审查-部署" tabindex="-1">6.4 开发提效链路：代码生成+审查+部署 <a class="header-anchor" href="#_6-4-开发提效链路-代码生成-审查-部署" aria-label="Permalink to “6.4 开发提效链路：代码生成+审查+部署”">​</a></h2><p><strong>链路设计</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>需求分析 → 代码生成 → 代码审查 → 测试 → 部署 → 监控</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>各环节工具</strong></p><table tabindex="0"><thead><tr><th>环节</th><th>工具</th><th>职责</th></tr></thead><tbody><tr><td>需求分析</td><td>OpenWebUI + DeepSeek-R1</td><td>需求拆解、技术方案</td></tr><tr><td>代码生成</td><td>Cline + DeepSeek-Coder</td><td>自主编写代码</td></tr><tr><td>代码补全</td><td>Continue + Qwen2.5-Coder</td><td>实时补全</td></tr><tr><td>代码审查</td><td>Continue Chat</td><td>选中代码→AI审查</td></tr><tr><td>测试生成</td><td>Continue Actions</td><td>自动生成单元测试</td></tr><tr><td>文档生成</td><td>Continue Actions</td><td>自动生成注释和文档</td></tr><tr><td>CI/CD</td><td>n8n + Git</td><td>自动化部署流程</td></tr></tbody></table><p><strong>效率提升数据</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>无AI</th><th>AI辅助</th><th>提升幅度</th></tr></thead><tbody><tr><td>需求分析</td><td>2小时</td><td>30分钟</td><td>75%</td></tr><tr><td>编码实现</td><td>8小时</td><td>2小时</td><td>75%</td></tr><tr><td>代码审查</td><td>2小时</td><td>30分钟</td><td>75%</td></tr><tr><td>单元测试</td><td>3小时</td><td>45分钟</td><td>75%</td></tr><tr><td>技术文档</td><td>2小时</td><td>20分钟</td><td>83%</td></tr><tr><td>Bug调试</td><td>4小时</td><td>1小时</td><td>75%</td></tr><tr><td>合计</td><td>21小时</td><td>5.25小时</td><td>75%</td></tr></tbody></table><h2 id="_6-5-成本与隐私-开源vs闭源的长期tco对比" tabindex="-1">6.5 成本与隐私：开源vs闭源的长期TCO对比 <a class="header-anchor" href="#_6-5-成本与隐私-开源vs闭源的长期tco对比" aria-label="Permalink to “6.5 成本与隐私：开源vs闭源的长期TCO对比”">​</a></h2><p><strong>三年总持有成本（TCO）对比</strong></p><table tabindex="0"><thead><tr><th>方案</th><th>初始成本</th><th>年运营成本</th><th>三年TCO</th><th>隐私</th></tr></thead><tbody><tr><td>全商业方案</td><td>$0</td><td>$1200-3600</td><td>$3600-10800</td><td>云端</td></tr><tr><td>全开源本地</td><td>$2000（硬件）</td><td>$500（电费）</td><td>$3500</td><td>完全本地</td></tr><tr><td>混合方案</td><td>$1000</td><td>$300-800</td><td>$1900-3400</td><td>分层</td></tr><tr><td>开源+API</td><td>$0</td><td>$200-600</td><td>$600-1800</td><td>部分云端</td></tr></tbody></table><p><strong>混合方案推荐</strong></p><table tabindex="0"><thead><tr><th>场景</th><th>方案</th><th>理由</th></tr></thead><tbody><tr><td>敏感代码</td><td>本地模型</td><td>数据不外泄</td></tr><tr><td>日常补全</td><td>本地Qwen2.5-Coder</td><td>免费且够用</td></tr><tr><td>复杂重构</td><td>DeepSeek API</td><td>便宜且强大</td></tr><tr><td>图片生成</td><td>本地FLUX.1 schnell</td><td>一次部署长期用</td></tr><tr><td>文档翻译</td><td>本地Ollama</td><td>隐私保护</td></tr><tr><td>知识库</td><td>本地FastGPT</td><td>数据自主</td></tr><tr><td>自动化</td><td>本地n8n</td><td>系统集成</td></tr></tbody></table><blockquote><p>最优策略：80%用本地开源工具，20%按需调API。三年省下至少$5000，还拿到了数据主权。</p></blockquote><hr><p>你最想打通的是哪两个工具之间的链路？评论区说说，下期可能就演示你的场景。</p><p>收藏这章，全场景工具选型决策树建议永久保存。</p><p>关注怕浪猫，下期讲部署与上手——从零搭建你的AI工具箱。</p><p>系列进度 6/8 — 下一篇：从零部署你的AI工具箱</p>`,43)])])}const g=d(e,[["render",r]]);export{c as __pageData,g as default};
